use vstd::prelude::*;

verus! {
    fn polymulx(c: Vec<f32>) -> (result: Vec<f32>)
        ensures
            // The output length is exactly one more than the input length
            result.len() == c.len() + 1,
            // The first element is exactly 0.0
            result[0] == 0.0,
            // For every valid input index k, result[k+1] == c[k]
            forall |k: usize| k < c.len() ==> result[k + 1] == c[k],
    {
        // Allocate the result and push the leading 0.0
        let mut result: Vec<f32> = Vec::new();
        result.push(0.0);

        // i = number of elements of `c` copied so far
        let mut i: usize = 0;
        while i < c.len()
            invariant
                // 0 <= i <= c.len()
                i <= c.len(),
                // So far we've constructed a result of length i+1
                result.len() == i + 1,
                // The first element remains 0.0
                result[0] == 0.0,
                // And for every k < i, result[k+1] == c[k]
                forall |k: usize| k < i ==> result[k + 1] == c[k],
            decreases c.len() - i,
        {
            // Copy one more element from c into result
            let x: f32 = c[i];
            result.push(x);
            i += 1;
        }

        result
    }
}

